import{_ as t,H as p,f as a,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"回信 | 编辑手记","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/回信｜编辑手记.md","filePath":"去无方向的信/回信｜编辑手记.md","lastUpdated":1795542896000}'),s={name:"去无方向的信/回信｜编辑手记.md"};function n(E,e,o,r,B,l){return p(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="回信-编辑手记" tabindex="-1">回信 | 编辑手记 <a class="header-anchor" href="#回信-编辑手记" aria-label="Permalink to &quot;回信 | 编辑手记&quot;">​</a></h1><p>生生：</p><p>你好呀。</p><p>我是《去无方向的信》的编辑晓蕾。这是一封写给我们每个人自己的，关于这套专栏的回信。</p><p>不用怕，这套专栏的内容还没有结束，就和课程目录图最下面的那句话一样，“且没完呢”。但是目前为止，他确实已经到了一定的阶段，在过两天更新完第六十九封信之后，就要休息一段儿时间了。我们一定会在第七十封信再见面，不过具体是什么时候……也说不准。</p><p>在这封信里，你可以通过下面图片描述的方式告诉我们一些你想看的有关摄影的内容，也可以聊一聊你对专栏的想法。至于我，就在第六十九封信之前插一脚，和你聊聊这套专栏的事儿吧。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E5%259B%259E%25E4%25BF%25A1/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E5%259B%259E%25E4%25BF%25A1/1.png" alt=""></a></p><p>我对这套专栏的喜欢来自很多很多封信。</p><p>比如第三十封信，《全宇宙最好用的相机》，他让我买东西的时候“颜控”得更有底气了；比如第四十六封信，《贪嗔痴慢疑》，他让我也能够直视自己内心那些可能“不太好”的想法；比如第五十八封信，《你拍的不够好，是因为你离的不够远》，就像我推翻了很多次这封回信一样，我切换着读者和编辑这两个视角，生怕内容和心情一样混乱；比如第六十五封信，《心理障碍和道德困境》，让我想起以前做助教的时候，在“朋友”和“师生”这两种关系之间的摇摆。</p><p>是的，除了摄影方面认知的提升，这套专栏也正如小麥说的，聊了更多的比拍照片重要得多的事儿，让我想起了更多和拍照片这件事相似的点点滴滴，给了我不小的帮助。</p><p>不过既然我们已经更新到了第六十八封信，那就顺着这封信再继续聊聊。</p><p>第一次看第六十八封信的时候是一个早晨，我还没从被窝里出来，本来泪点就低的我在看到那句“不要等，就从今天开始”的时候，眼泪就已经要出来了。鬼使神差地，我在这段话下面回复了这封信的唯一一个批注：好。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E5%259B%259E%25E4%25BF%25A1/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E5%259B%259E%25E4%25BF%25A1/2.png" alt=""></a></p><ul><li>然后小麥隔了很久才回了这个批注。我：忐忑。</li></ul><p>那个时候，我负责的第一个专栏已经结课了，小麥的稿件也定得差不多了。两套专栏一个接一个的结束，那种“结课后可能就会生疏”的心情让我难过了很长时间。</p><p>那么这第六十八封信对我来说，意味着什么呢？比如，他安抚了我持续两周的难过。再比如，他让我有了想马上做点什么的冲动。画画？读书？很多很多，甚至是看一篇新的稿件，不知道，方向很多，但他的确把我往前推了推，给了我再往前看一点的勇气，不再和心底的不安死缠烂打。</p><p>可是如果再把时间拉长，在之后的几周里，也是第六十八封信，也是“好就好～”的回复给了我再往前看一点的勇气吗？</p><p>这封信的写作过程断断续续的，在这几周的时间里，我捡起了之前很久没有练习的速涂。找形，练习色感，我清楚地记得从已经开始忘记怎么临摹到终于又完成一幅画的兴奋和满足，然后就这样继续一张又一张地画。如果你往下翻，就会发现不自量力的我已经开始尝试创作了。</p><p>所以，我想我应该能稍稍总结出一点这个问题的答案。也许在未来更多的时间里，给我勇气和动力的会是这些我切实去做的事，是我切实的积累，是他们把我往前推了又推。慢慢练下去，也许有一天我还会用他记录生活，甚至有自己的画风，我要去学习那些喜欢但一直没有开始的事情，再去体会更多的滋味。</p><p>小麥的直播里常常能看到那些开在路边的大红色的蔷薇，那些花儿和我平常看到的在马路边排列组合好的花完全不同，他们好像带着一股劲儿，那里面有更多的自由和生命力，带着这股劲儿，他们无所畏惧地向上生长。</p><p>真希望我也能成为这株蔷薇。</p><p>真希望你也能从这套专栏里得到一些乱七八糟、奇奇怪怪的有趣想法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E5%259B%259E%25E4%25BF%25A1/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E5%259B%259E%25E4%25BF%25A1/3.png" alt=""></a></p><p>最后，为什么要在一开始说“不用怕”呢？当然是怕你和我一样舍不得和这套专栏短暂的分别啦。在这一封信发出去之后，一直到第六十九封信发出，我们就要等一段时间再见了。</p><p>别难过，咱们第七十封信再继续聊。</p>',25)])])}const c=t(s,[["render",n]]);export{h as __pageData,c as default};
